"""Frozen opaque dependency guard for common whole-run rollback."""

SQL = "CREATE FUNCTION revert_subjects_consumed(t uuid,c uuid,targets jsonb,own_receipts uuid[])\nRETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$\nDECLARE tables text[]=ARRAY['action_receipts','actual_configurations','artifact_versions','audit_entries','bom_lines','bom_revisions','build_authorization_decisions','build_current_authorizations','build_current_execution_assessments','build_execution_assessments','build_lots','build_operational_current','build_operational_facts','build_readiness','build_starts','builds','capa_current_observations','capa_current_verification_rules','capa_named_verification_reviews','capa_observation_facts','capa_remediation_links','capa_verification_evidence','capa_verification_rule_facts','change_approval_records','change_dependency_clocks','change_graph_captures','change_implementation_captures','change_implementation_records','change_order_records','change_request_currents','change_request_versions','claim_consumptions','claims','controlled_change_coverage_currents','controlled_change_coverage_facts','controlled_change_policy_currents','controlled_change_policy_facts','controlled_change_selection_currents','controlled_change_selection_facts','cost_current_inputs','cost_estimates','cost_input_snapshots','cost_source_captures','definition_revisions','definition_sources','definition_specs','engineering_configurations','manufacturing_baseline_document_links','manufacturing_preparation_currents','manufacturing_preparation_versions','measurement_import_captures','operational_material_holds','operational_resource_occupancies','original_scan_requests','original_scan_results','original_security','outbox_events','parts','plan_proposals','plan_revisions','process_revisions','product_variants','professional_authority_current','professional_authority_facts','project_product_links','project_tasks','project_work_packages','projects','quality_current_issues','quality_current_policies','quality_event_failure_links','quality_failure_maps','quality_issue_versions','quality_policy_facts','request_keys','runs','sample_allocations','sample_current_readiness','sample_readiness_facts','sample_run_usages','sample_units','sample_usage_sentinels','supply_current_snapshots','supply_kit_projections','supply_snapshots','supply_source_captures','task_dependencies','test_measurements','test_resource_current','test_resource_facts','test_resource_reservations','test_result_actions','test_result_projections','uploaded_originals','variant_revisions','verification_actual_method_applicabilities','verification_actual_method_batches','verification_current_actual_methods','verification_current_formal_requests','verification_current_preparations','verification_current_runs','verification_formal_requests','verification_handoff_facts','verification_launch_facts','verification_method_applicabilities','verification_preparations','verification_run_identities','verification_run_versions','verification_window_proposals','work_requests']; table_name text; target jsonb; ids uuid[]='{}'; payload jsonb;\nBEGIN\n IF NOT category_access(t,c,true) OR jsonb_typeof(targets)<>'array' THEN RETURN true; END IF;\n FOR target IN SELECT v FROM jsonb_array_elements(targets) AS x(v) LOOP\n  IF target->>'type'='claim' THEN\n   IF NOT EXISTS (SELECT 1 FROM claims a WHERE a.tenant_id=t AND a.category_id=c AND a.id=(target->>'id')::uuid\n      AND a.human_owner_id=scope_requester() AND source_object_audience(t,c,'claims',a.id,a.human_owner_id,a.visibility))\n    THEN RETURN true; END IF;\n  ELSIF target->>'type'='artifact' THEN\n   IF NOT EXISTS (SELECT 1 FROM artifact_versions a WHERE a.tenant_id=t AND a.category_id=c AND a.id=(target->>'id')::uuid\n      AND a.owner_id=scope_requester() AND direct_source_set_visible(t,c,a.product_id,jsonb_build_array(jsonb_build_object('artifact_id',a.id))))\n    THEN RETURN true; END IF;\n  ELSE RETURN true; END IF;\n  ids=array_append(ids,(target->>'id')::uuid);\n END LOOP;\n FOREACH table_name IN ARRAY tables LOOP\n  FOR payload IN EXECUTE format('SELECT to_jsonb(x) FROM public.%I x WHERE tenant_id=$1 AND category_id=$2',table_name) USING t,c LOOP\n   IF (payload->>'id')::uuid=ANY(ids) OR (payload->>'id')::uuid=ANY(own_receipts)\n      OR (payload->>'receipt_id')::uuid=ANY(own_receipts) THEN CONTINUE; END IF;\n   IF lifecycle_payload_links(payload) && ids THEN RETURN true; END IF;\n  END LOOP;\n END LOOP;\n RETURN false;\nEND $$"
